// =========================================================================
// MESIN OTOMASI MYSIMS (LOGIN + MULTIPART/FALLBACK + SCRAPE + CALLBACK DIRECT)
// =========================================================================

const webhookData = $('Webhook Trigger').first().json.body || $('Webhook Trigger').first().json || {};
const cutiId = webhookData.cuti_id || '';
const namaPegawai = webhookData.nama_pegawai || 'Pegawai';
const jenisCuti = webhookData.jenis_cuti || 'Tahunan';
const callbackUrl = webhookData.callback_url || '';
const secretKey = webhookData.secret_key || 'TRANSKEP_WA_BOT_2026';

const mysims = webhookData.mysims_payload || {};
const dari = mysims.dari || namaPegawai;
const uraian = mysims.uraian || ('Permohonan Cuti ' + jenisCuti + ' a.n. ' + namaPegawai);
const kode = mysims.kode || 'KP5.3';
const tglSurat = mysims.tgl_surat || new Date().toISOString().slice(0, 10);
const ket = mysims.ket || ('cuti ' + jenisCuti.toLowerCase());
const sifatDefault = 'Biasa';

const pdfBase64 = webhookData.pdf_base64 || '';
const cleanFirst = String(dari).replace(/[^a-zA-Z0-9]/g, ' ').trim().split(/\s+/)[0].toLowerCase();
const pdfFileName = webhookData.pdf_filename || ('TRANSKEP_' + cleanFirst + '_ct.pdf');

let sessionCookie = '';
let nomorSurat = '';
let debugLog = [];

// -------------------------------------------------------------------------
// LANGKAH 1: LOGIN KE MYSIMS (Menangkap Cookie ci_session)
// -------------------------------------------------------------------------
debugLog.push('1. Login ke MYSIMS...');
try {
  const loginBody = 'u=' + encodeURIComponent('ketua') + '&p=' + encodeURIComponent('admin') + '&ta=' + encodeURIComponent('2026');
  const loginResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://192.168.188.10/mysim/index.php/admin/do_login',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) TRANSKEP-Bot/1.0'
    },
    body: loginBody,
    disableFollowRedirect: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });

  const headers = loginResp.headers || {};
  const rawCookies = headers['set-cookie'] || [];
  const list = Array.isArray(rawCookies) ? rawCookies : (rawCookies ? [rawCookies] : []);
  const cookieParts = list.map(c => String(c).split(';')[0].trim()).filter(Boolean);
  sessionCookie = cookieParts.join('; ');
  debugLog.push('Login: ' + (sessionCookie ? 'OK' : 'KOSONG'));
} catch (errLogin) {
  debugLog.push('Login err: ' + errLogin.message);
}

// -------------------------------------------------------------------------
// LANGKAH 2: CEK DAFTAR SURAT AWAL (Catat Nomor Teratas Saat Ini)
// -------------------------------------------------------------------------
let previousTopNumber = '';
let sifatVal = sifatDefault;
try {
  const initList = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://192.168.188.10/mysim/index.php/admin/surat_keluar',
    headers: {
      'Cookie': sessionCookie,
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) TRANSKEP-Bot/1.0'
    },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
  const initHtml = String(initList.body || initList.data || '');
  const mInit = initHtml.match(/(\d+\/KPA\.W10-A2\/[A-Za-z0-9.]+\/[IVXLCDM]+\/\d{4})/i);
  if (mInit && mInit[1]) {
    previousTopNumber = mInit[1].trim();
    debugLog.push('Nomor awal MYSIMS: ' + previousTopNumber);
  }

  // Deteksi option value untuk kata "Biasa"
  const optMatch = initHtml.match(/<option[^>]*value=["']([^"']*)["'][^>]*>\s*Biasa\s*<\/option>/i);
  if (optMatch && optMatch[1] !== undefined && optMatch[1].trim() !== '') {
    sifatVal = optMatch[1].trim();
    debugLog.push('Option sifat: ' + sifatVal);
  }
} catch (eInit) {
  debugLog.push('Cek awal: ' + eInit.message);
}

// -------------------------------------------------------------------------
// LANGKAH 3: SUBMIT FORMULIR SURAT KELUAR MYSIMS (MULTIPART FORM + FILE PDF)
// -------------------------------------------------------------------------
debugLog.push('2. Submit surat keluar...');
let submitSuccess = false;

try {
  const boundary = '----WebKitFormBoundary' + Math.random().toString(36).substring(2) + Date.now().toString(36);
  const chunks = [];

  const addPart = (k, v) => {
    chunks.push(Buffer.from(
      '--' + boundary + '\r\n' +
      'Content-Disposition: form-data; name="' + k + '"\r\n\r\n' +
      v + '\r\n'
    ));
  };

  addPart('idp', '');
  addPart('no_agenda', '');
  addPart('dari', dari);
  addPart('no_surat', 'KPA.W10-A2/');
  addPart('uraian', uraian);
  addPart('kode', kode);
  addPart('tgl_surat', tglSurat);
  addPart('sifat', sifatVal);
  addPart('sifat_surat', sifatVal);
  addPart('ket', ket);
  addPart('submit', 'Simpan');
  addPart('simpan', 'Simpan');

  if (pdfBase64 && pdfBase64.length > 50) {
    const pdfBuf = Buffer.from(pdfBase64, 'base64');
    chunks.push(Buffer.from(
      '--' + boundary + '\r\n' +
      'Content-Disposition: form-data; name="file_surat"; filename="' + pdfFileName + '"\r\n' +
      'Content-Type: application/pdf\r\n\r\n'
    ));
    chunks.push(pdfBuf);
    chunks.push(Buffer.from('\r\n'));
    debugLog.push('PDF terlampir: ' + pdfFileName + ' (' + pdfBuf.length + ' bytes)');
  } else {
    chunks.push(Buffer.from(
      '--' + boundary + '\r\n' +
      'Content-Disposition: form-data; name="file_surat"; filename=""\r\n' +
      'Content-Type: application/octet-stream\r\n\r\n\r\n'
    ));
  }

  chunks.push(Buffer.from('--' + boundary + '--\r\n'));
  const bodyBuffer = Buffer.concat(chunks);

  const addResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://192.168.188.10/mysim/index.php/admin/surat_keluar/act_add',
    headers: {
      'Cookie': sessionCookie,
      'Content-Type': 'multipart/form-data; boundary=' + boundary,
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) TRANSKEP-Bot/1.0'
    },
    body: bodyBuffer,
    disableFollowRedirect: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });

  debugLog.push('Submit multipart status: ' + (addResp.statusCode || addResp.status));
} catch (errSubmit) {
  debugLog.push('Submit multipart err: ' + errSubmit.message);
}

// -------------------------------------------------------------------------
// LANGKAH 4: CEK DAFTAR SURAT TERBARU & VALIDASI NOMOR BARU
// -------------------------------------------------------------------------
try {
  const listResp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://192.168.188.10/mysim/index.php/admin/surat_keluar',
    headers: {
      'Cookie': sessionCookie,
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) TRANSKEP-Bot/1.0'
    },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });

  const htmlContent = String(listResp.body || listResp.data || listResp || '');
  const match = htmlContent.match(/(\d+\/KPA\.W10-A2\/[A-Za-z0-9.]+\/[IVXLCDM]+\/\d{4})/i);
  if (match && match[1]) {
    const candidate = match[1].trim();
    if (candidate !== previousTopNumber) {
      nomorSurat = candidate;
      submitSuccess = true;
      debugLog.push('BERHASIL! Nomor baru: ' + nomorSurat);
    }
  }
} catch (errCheck) {
  debugLog.push('Check list err: ' + errCheck.message);
}

// -------------------------------------------------------------------------
// LANGKAH 4.5: FALLBACK URL-ENCODED (Jika multipart tidak menghasilkan nomor baru)
// -------------------------------------------------------------------------
if (!submitSuccess) {
  debugLog.push('Fallback urlencoded...');
  try {
    const formParams = {
      idp: '',
      no_agenda: '',
      dari: dari,
      no_surat: 'KPA.W10-A2/',
      uraian: uraian,
      kode: kode,
      tgl_surat: tglSurat,
      sifat: sifatVal,
      sifat_surat: sifatVal,
      ket: ket,
      submit: 'Simpan',
      simpan: 'Simpan'
    };

    const formBody = Object.keys(formParams)
      .map(k => encodeURIComponent(k) + '=' + encodeURIComponent(formParams[k]))
      .join('&');

    const fbResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://192.168.188.10/mysim/index.php/admin/surat_keluar/act_add',
      headers: {
        'Cookie': sessionCookie,
        'Content-Type': 'application/x-www-form-urlencoded',
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) TRANSKEP-Bot/1.0'
      },
      body: formBody,
      disableFollowRedirect: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true
    });

    debugLog.push('Fallback status: ' + (fbResp.statusCode || fbResp.status));

    const listResp2 = await this.helpers.httpRequest({
      method: 'GET',
      url: 'http://192.168.188.10/mysim/index.php/admin/surat_keluar',
      headers: {
        'Cookie': sessionCookie,
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) TRANSKEP-Bot/1.0'
      },
      returnFullResponse: true,
      ignoreHttpStatusErrors: true
    });

    const htmlContent2 = String(listResp2.body || listResp2.data || '');
    const match2 = htmlContent2.match(/(\d+\/KPA\.W10-A2\/[A-Za-z0-9.]+\/[IVXLCDM]+\/\d{4})/i);
    if (match2 && match2[1]) {
      nomorSurat = match2[1].trim();
      debugLog.push('BERHASIL via Fallback! Nomor: ' + nomorSurat);
    }
  } catch (errFb) {
    debugLog.push('Fallback err: ' + errFb.message);
  }
}

// -------------------------------------------------------------------------
// LANGKAH 5: CALLBACK KE TRANSKEP (Update Nomor Surat Resmi ke cuti_log)
// -------------------------------------------------------------------------
if (nomorSurat && callbackUrl) {
  debugLog.push('Kirim callback ke TRANSKEP: ' + nomorSurat);
  try {
    const cbResp = await this.helpers.httpRequest({
      method: 'POST',
      url: callbackUrl,
      headers: {
        'Content-Type': 'application/json',
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) TRANSKEP-Bot/1.0'
      },
      body: JSON.stringify({
        action: 'updateNomorSuratCuti',
        id: cutiId,
        nomor_surat: nomorSurat,
        secret_key: secretKey
      }),
      disableFollowRedirect: false,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true
    });
    debugLog.push('Callback TRANSKEP: ' + (cbResp.statusCode || cbResp.status));
  } catch (errCb) {
    debugLog.push('Callback TRANSKEP err: ' + errCb.message);
  }
} else {
  debugLog.push('Callback dilewati (Nomor/URL kosong)');
}

return [{
  json: {
    cuti_id: cutiId,
    nomor_surat: nomorSurat,
    secret_key: secretKey,
    callback_url: callbackUrl,
    nama_pegawai: namaPegawai,
    debug_log: debugLog.join(' | ')
  }
}];
